CREATE TABLE wfc_grid3d_document (id INTEGER PRIMARY KEY, schema_id TEXT NOT NULL, seed TEXT NOT NULL, width INTEGER NOT NULL CHECK(width BETWEEN 0 AND 4294967295), height INTEGER NOT NULL CHECK(height BETWEEN 0 AND 4294967295), depth INTEGER NOT NULL CHECK(depth BETWEEN 0 AND 4294967295), periodic_x INTEGER NOT NULL CHECK(periodic_x IN(0,1)), periodic_y INTEGER NOT NULL CHECK(periodic_y IN(0,1)), periodic_z INTEGER NOT NULL CHECK(periodic_z IN(0,1)));
CREATE TABLE wfc_grid3d_cell_size (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc_grid3d_document(id), axis TEXT NOT NULL CHECK(axis IN('x','y','z')), ordinal INTEGER NOT NULL CHECK(ordinal>=0), size REAL, size_bits INTEGER NOT NULL, size_class TEXT NOT NULL);
CREATE TABLE wfc_grid3d_tile (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc_grid3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), authored_id TEXT NOT NULL, label TEXT, weight REAL, media_kind TEXT NOT NULL CHECK(media_kind IN('mesh','mesh_child')), weight_bits INTEGER NOT NULL, weight_class TEXT NOT NULL);
CREATE TABLE wfc_grid3d_mesh (id INTEGER PRIMARY KEY REFERENCES wfc_grid3d_tile(id));
CREATE TABLE wfc_grid3d_position (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES wfc_grid3d_mesh(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), coordinate REAL, coordinate_bits INTEGER NOT NULL, coordinate_class TEXT NOT NULL);
CREATE TABLE wfc_grid3d_index (id INTEGER PRIMARY KEY, mesh_id INTEGER NOT NULL REFERENCES wfc_grid3d_mesh(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), vertex_index INTEGER NOT NULL CHECK(vertex_index BETWEEN 0 AND 4294967295));
CREATE TABLE wfc_grid3d_color (id INTEGER PRIMARY KEY REFERENCES wfc_grid3d_mesh(id), red INTEGER NOT NULL CHECK(red BETWEEN 0 AND 4294967295), green INTEGER NOT NULL CHECK(green BETWEEN 0 AND 4294967295), blue INTEGER NOT NULL CHECK(blue BETWEEN 0 AND 4294967295), alpha INTEGER NOT NULL CHECK(alpha BETWEEN 0 AND 4294967295));
CREATE TABLE wfc_grid3d_mesh_child (id INTEGER PRIMARY KEY REFERENCES wfc_grid3d_tile(id), child_id TEXT NOT NULL, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE wfc_grid3d_rule (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc_grid3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), authored_id TEXT NOT NULL, tile_a_id INTEGER NOT NULL REFERENCES wfc_grid3d_tile(id), tile_b_id INTEGER NOT NULL REFERENCES wfc_grid3d_tile(id), direction TEXT NOT NULL CHECK(direction IN('LEFT','RIGHT','FRONT','BACK','BOTTOM','TOP')), allowed INTEGER NOT NULL CHECK(allowed IN(0,1)));
CREATE TABLE wfc_grid3d_pin (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc_grid3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), x INTEGER NOT NULL CHECK(x BETWEEN 0 AND 4294967295), y INTEGER NOT NULL CHECK(y BETWEEN 0 AND 4294967295), z INTEGER NOT NULL CHECK(z BETWEEN 0 AND 4294967295), tile_id INTEGER NOT NULL REFERENCES wfc_grid3d_tile(id));
CREATE TABLE wfc_grid3d_mask (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES wfc_grid3d_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), x INTEGER NOT NULL CHECK(x BETWEEN 0 AND 4294967295), y INTEGER NOT NULL CHECK(y BETWEEN 0 AND 4294967295), z INTEGER NOT NULL CHECK(z BETWEEN 0 AND 4294967295));
